<div class="section-heading studio-section-heading"><div><span class="website-kicker">LIVE WEBSITE WORKSPACE</span><h2>Connected website</h2><p class="muted">Load and edit the real collections exposed by this website’s adapter.</p></div><a href="/websites/<?= $siteId ?>">Connection settings</a></div>
<?php if(!$connection): ?><section class="card studio-empty"><span class="studio-empty-icon"><?= icon('grid') ?></span><h3>Sign in to your website first.</h3><p class="muted">Your local Studio is ready to use. Live records require your provider or website account.</p><div class="hero-actions"><a class="btn" href="/websites#provider-login">Provider sign-in</a><a href="/websites/<?= $siteId ?>">Website sign-in</a></div></section><?php else: ?>
<section class="card"><div class="section-heading"><div><h3><?= e($connection['manifest']['site']['name']) ?></h3><p class="muted"><?= e($connection['username'] ?: 'Connected API session') ?> · Session ends <?= e(date('H:i',$connection['expires_at'])) ?></p></div><span class="badge">Website API connected</span></div><nav class="studio-remote-tabs" aria-label="Website collections"><?php foreach($connection['manifest']['collections'] as $item): ?><a href="<?= $studioPath ?>?section=connected&amp;collection=<?= e($item['id']) ?>" <?= ($remoteCollection['id'] ?? '')===$item['id']?'class="selected" aria-current="page"':'' ?>><?= e($item['label']) ?></a><?php endforeach; ?></nav></section>
<?php if($remoteCollection): $remoteSlug=$remoteCollection['id'];$capabilities=$remoteCollection['capabilities']; ?>
<section class="card"><div class="section-heading"><div><h3><?= e($remoteCollection['label']) ?></h3><p class="muted"><?= $remoteCache?e($remoteCache['total']).' records · Loaded '.e($remoteCache['fetched_at']):'Load this collection to retrieve its website records.' ?></p></div><form action="<?= $studioPath ?>/remote/refresh" method="post"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($remoteSlug) ?>"><input type="hidden" name="offset" value="<?= e($remoteCache['offset'] ?? 0) ?>"><button class="secondary">Load / refresh</button></form></div>
<?php if($remoteCache && !$remoteCache['records']): ?><p class="studio-empty muted">This website returned no records for this collection.</p><?php endif; ?>
<?php foreach($remoteCache['records'] ?? [] as $record): ?><article class="studio-remote-record"><div class="section-heading"><h3><?= e($record['data'][$remoteCollection['fields'][0]['name']] ?? $record['id']) ?></h3><span class="badge">Version <?= e($record['version']) ?></span></div><dl class="website-record-values"><?php foreach($remoteCollection['fields'] as $field): $value=$record['data'][$field['name']] ?? '';if(is_bool($value))$value=$value?'Yes':'No'; ?><div><dt><?= e($field['label']) ?></dt><dd><?= e(mb_strimwidth((string)$value,0,400,'…')) ?></dd></div><?php endforeach; ?></dl><div class="hero-actions"><?php if(in_array('update',$capabilities,true)): ?><a class="btn secondary" href="<?= $studioPath ?>?section=connected&amp;collection=<?= e($remoteSlug) ?>&amp;edit=<?= e(rawurlencode($record['id'])) ?>#studio-remote-editor">Edit website record</a><?php endif; ?><?php if(in_array('delete',$capabilities,true)): ?><form method="post" action="<?= $studioPath ?>/remote/delete" data-confirm="Delete this record from the connected website? This changes remote data."><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($remoteSlug) ?>"><input type="hidden" name="record_id" value="<?= e($record['id']) ?>"><input type="hidden" name="version" value="<?= e($record['version']) ?>"><button class="delete">Delete from website</button></form><?php endif; ?></div></article><?php endforeach; ?>
<?php if($remoteCache): ?><div class="studio-pagination"><?php foreach(['Previous'=>max(0,$remoteCache['offset']-$remoteCache['limit']),'Next'=>$remoteCache['offset']+$remoteCache['limit']] as $label=>$offset):if(($label==='Previous' && $remoteCache['offset']===0) || ($label==='Next' && $offset>=$remoteCache['total']))continue; ?><form method="post" action="<?= $studioPath ?>/remote/refresh"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($remoteSlug) ?>"><input type="hidden" name="offset" value="<?= $offset ?>"><button class="secondary"><?= $label ?></button></form><?php endforeach; ?></div><?php endif; ?></section>
<?php if(($edit && in_array('update',$capabilities,true)) || (!$edit && in_array('create',$capabilities,true))): ?><section class="card studio-editor" id="studio-remote-editor"><h2><?= $edit?'Edit website record':'Create website record' ?></h2><p class="muted">Submitting this form writes to the connected website.</p><form class="form-grid" action="<?= $studioPath ?>/remote/save" method="post"><?= csrf_field() ?><input type="hidden" name="collection" value="<?= e($remoteSlug) ?>"><?php if($edit): ?><input type="hidden" name="record_id" value="<?= e($edit['id']) ?>"><input type="hidden" name="version" value="<?= e($edit['version']) ?>"><?php endif; ?><?php foreach($remoteCollection['fields'] as $field):$name='fields['.$field['name'].']';$value=$edit['data'][$field['name']] ?? ''; ?><label class="<?= $field['type']==='textarea'?'full':'' ?>"><?= e($field['label']) ?><?= $field['required']?' *':'' ?><?php if($field['type']==='textarea'): ?><textarea name="<?= e($name) ?>" maxlength="<?= e($field['max_length']) ?>" rows="5" <?= $field['required']?'required':'' ?>><?= e($value) ?></textarea><?php elseif($field['type']==='boolean'): ?><input type="hidden" name="<?= e($name) ?>" value="0"><input type="checkbox" name="<?= e($name) ?>" value="1" <?= $value?'checked':'' ?>><?php else: ?><input name="<?= e($name) ?>" type="<?= e(in_array($field['type'],['number','date'],true)?$field['type']:'text') ?>" value="<?= e($value) ?>" maxlength="<?= e($field['max_length']) ?>" <?= $field['type']==='number'?'step="any"':'' ?> <?= $field['required']?'required':'' ?>><?php endif; ?></label><?php endforeach; ?><div class="full studio-form-footer"><button><?= $edit?'Save to website':'Create on website' ?></button><?php if($edit): ?><a href="<?= $studioPath ?>?section=connected&amp;collection=<?= e($remoteSlug) ?>">Cancel edit</a><?php endif; ?></div></form></section><?php endif; ?>
<?php else: ?><section class="card"><p class="muted">This website account has no available collections.</p></section><?php endif; endif; ?>
